end if;

-- Ruang Ranum, di belakang ruang terakhir (dilewati bila id atau alamatnya sudah dipakai)
select coalesce(max(sort), 0) into next_sort from public.projects;
insert into public.projects (id, slug, sort, published, data) select 'a3299df1-e863-5bc9-b6ad-881a68531433', 'ranum', next_sort + 1, true, '{"name":"Ranum","mapLabel":"Ranum","mapSlot":12,"titleFont":"ranum","titleStyle":{"size":"xxl","uppercase":false,"weight":400,"tracking":-0.02},"meta":{"id":"Merek tabir surya, 2026","en":"Sunblock brand, 2026"},"text":{"id":"Situs toko untuk merek tabir surya dengan empat formula, masing-masing dinamai menurut tempat tujuannya: jalan kota, jalur hutan, jalan gurun, dan pantai tropis. Saat digulir, warna, bunga timbul, dan tube-nya berganti mengikuti tempat itu, dua pertanyaan memilihkan satu formula beserta alasannya, dan kotaknya terlipat dari selembar kertas.","en":"A shop for a sunblock brand with four formulas, each named after where it is headed: city streets, forest trails, desert roads and the tropical coast. As you scroll, the colour, the pressed flower and the tube change with the place, two questions pick one formula and say why, and the box folds from a single sheet of paper."},"lines":["sell","found"],"theme":{"wall":"#D5AE91","ink":"#26443A","muted":"#553F30","accent":"#26443A","btnBg":"#26443A","btnInk":"#F0E2C7"},"facts":[{"value":"4","label":{"id":"formula, satu untuk setiap tempat","en":"formulas, one for each place"}},{"value":"2","label":{"id":"pertanyaan untuk menemukan formulanya","en":"questions to find yours"}},{"value":"6","label":{"id":"bunga timbul di kotak kertas","en":"flowers pressed into paper boxes"}}],"status":{"id":"Preview desain, belum tayang","en":"Design preview, not live yet"},"liveUrl":"","liveLabel":"","liveNote":null,"previewUrl":"/preview/ranum.html","layout":"desk-phone","visuals":[{"role":"desk","image":{"url":"/media/seed/live/ranum-desk.webp","alt":{"id":"Beranda Ranum: wajah perempuan di air, wordmark Ranum besar, dan judul Protect your skin wherever the sun takes you","en":"Ranum homepage: a woman''s face in the water, the large Ranum wordmark and the headline Protect your skin wherever the sun takes you"},"width":1600,"height":1000},"video":{"url":"/media/seed/live/ranum-desk.mp4"}},{"role":"phone","image":{"url":"/media/seed/live/ranum-phone.webp","alt":{"id":"Beranda Ranum di HP: wajah perempuan di air, judul Protect your skin wherever the sun takes you, dan wordmark Ranum","en":"Ranum homepage on phone: a woman''s face in the water, the headline Protect your skin wherever the sun takes you and the Ranum wordmark"},"width":600,"height":1298},"video":{"url":"/media/seed/live/ranum-phone.mp4"}}],"brand":null,"pattern":"none","motion":"sun","result":null,"mascot":{"image":{"url":"/media/seed/mascot/ranum.webp","alt":{"id":"Tube Forest Calm dari Ranum","en":"A Ranum Forest Calm tube"},"width":432,"height":1024},"motion":"float","size":160,"chip":""}}'::jsonb where not exists (select 1 from public.projects where id = 'a3299df1-e863-5bc9-b6ad-881a68531433' or slug = 'ranum');

-- Studi kasusnya (hanya untuk proyek Ranum yang baru ditambahkan, dan bila belum ada)
insert into public.case_studies (project_slug, published, data) select 'ranum', true, '{"subtitle":{"id":"Situs toko untuk merek tabir surya dengan empat formula yang dinamai menurut tempat tujuannya, dari pencari shade sampai kotak kertas yang terlipat sendiri.","en":"A shop for a sunblock brand whose four formulas are named after where they are headed, from a shade finder to a paper box that folds itself."},"labels":{"client":"Ranum","field":{"id":"Tabir surya","en":"Sunblock"},"role":{"id":"Desain situs, interaksi, dan front-end","en":"Site design, interaction and front-end"},"year":"2026"},"cover":{"url":"/media/seed/ranum-beranda.webp","alt":{"id":"Beranda Ranum: wajah perempuan di air, wordmark Ranum besar, dan judul Protect your skin wherever the sun takes you","en":"Ranum homepage: a woman''s face in the water, the large Ranum wordmark and the headline Protect your skin wherever the sun takes you"},"width":1600,"height":1000},"theme":{"wall":"#F7EFDF","ink":"#26443A","muted":"#4A5F55","accent":"#52667B","btnBg":"#26443A","btnInk":"#F0E2C7"},"blocks":[{"type":"prose","title":{"id":"Situasinya","en":"The situation"},"paragraphs":[{"id":"Ranum membuat tabir surya ringan untuk orang yang jarang berada lama di satu tempat. Ada empat formula, dan masing-masing dinamai menurut tempat tujuannya: Urban Shade untuk jalan kota, Forest Calm untuk jalur hutan, Desert Glow untuk jalan gurun, dan Tropical Defense untuk pantai tropis, ditambah The Journey Set yang berisi keempatnya.","en":"Ranum makes light sunblock for people who are rarely in one place for long. There are four formulas, each named after where it is headed: Urban Shade for city streets, Forest Calm for forest trails, Desert Glow for desert roads and Tropical Defense for the tropical coast, plus The Journey Set with all four."},{"id":"Situsnya harus menjual gagasan itu sebelum produknya: memilih menurut tempat, bukan angka SPF, dan tahu ke mana kemasannya pergi setelah habis. Hasilnya toko tujuh halaman dalam satu file, dari beranda sampai halaman terima kasih, yang bisa dicoba di desktop dan HP. Pembayarannya belum tersambung dan harganya masih contoh, karena situs ini masih preview desain.","en":"The site had to sell that idea before the product: choose by place rather than by SPF number, and know where the packaging goes once it is empty. The result is a seven-page shop in one file, from the homepage to the thank-you page, ready to try on desktop and phone. Payments aren''t connected and prices are placeholders, because the site is still a design preview."}]},{"type":"features","title":{"id":"Toko yang bisa dicoba","en":"A shop you can try"},"items":[{"title":{"id":"Empat terrain dalam satu gulir","en":"Four terrains in one scroll"},"text":{"id":"Satu bagian beranda tertahan di layar dan berjalan melewati keempat formula. Latar, bunga timbul, dan tube berganti bersama saat digulir, dan indeks terrain bisa melompat ke formula mana pun.","en":"One homepage section holds still and walks through the four formulas. The background, the pressed flower and the tube change together as you scroll, and the terrain index jumps to any of them."},"images":[{"url":"/media/seed/ranum-terrain.webp","alt":{"id":"Bagian terrain di beranda: Forest Calm SPF 40 dengan tube hijau dan bunga anggrek timbul di latar hijau tua","en":"The terrain section on the homepage: Forest Calm SPF 40 with a green tube and a pressed orchid on deep green"},"width":1600,"height":1000},{"url":"/media/seed/ranum-hp-terrain.webp","alt":{"id":"Bagian terrain di HP: Desert Glow SPF 50 dengan tube dan bunga timbul di latar pasir","en":"The terrain section on a phone: Desert Glow SPF 50 with its tube and pressed flower on sand"},"width":600,"height":1298}]},{"title":{"id":"Dua pertanyaan, satu formula","en":"Two questions, one formula"},"text":{"id":"Pencari shade bertanya ke mana pembeli pergi dan bagaimana kulitnya. Setiap jawaban naik menjadi label kecil, warna bagiannya berganti mengikuti tujuan, dan hasilnya menyebut satu formula beserta alasannya. Kulit bisa mengalahkan tempat: kulit sensitif yang pergi ke pantai tetap disarankan Forest Calm.","en":"The shade finder asks where the shopper is headed and how their skin feels. Each answer moves up into a small chip, the section takes the colour of the destination, and the result names one formula with the reason. Skin can overrule the place: sensitive skin headed for the coast still gets Forest Calm."},"images":[{"url":"/media/seed/ranum-finder.webp","alt":{"id":"Hasil pencari shade: Tropical coast dan Sensitive menghasilkan Forest Calm, dengan kalimat alasannya","en":"The shade finder result: Tropical coast and Sensitive lead to Forest Calm, with the sentence that explains why"},"width":1600,"height":1000},{"url":"/media/seed/ranum-hp-finder.webp","alt":{"id":"Hasil pencari shade di HP: Desert roads dan Dry menghasilkan Desert Glow","en":"The shade finder result on a phone: Desert roads and Dry lead to Desert Glow"},"width":600,"height":1298}]},{"title":{"id":"Kampanye dan tekstur krim","en":"The campaign and the cream"},"text":{"id":"Foto kampanye diambil di tempat formulanya dipakai, dan poster-posternya berjajar di beranda, bergeser dengan kecepatan berbeda saat digulir. Krimnya punya bagian sendiri: kanvas WebGL membengkokkan foto teksturnya mengikuti kursor, lalu membiarkannya kembali tenang. Tanpa WebGL, fotonya tetap tampil biasa.","en":"The campaign was shot where the formulas get used, and its posters sit side by side on the homepage, drifting at different speeds as you scroll. The cream gets a section of its own: a WebGL canvas bends the texture photo along the cursor, then lets it settle. Without WebGL, the photo simply stays as it is."},"images":[{"url":"/media/seed/ranum-kampanye.webp","alt":{"id":"Bagian Made to move with you: tiga poster kampanye Ranum berjajar","en":"The Made to move with you section: three Ranum campaign posters side by side"},"width":1600,"height":1000},{"url":"/media/seed/ranum-tekstur.webp","alt":{"id":"Bagian Feeling fresh, hours later: foto tekstur krim di samping daftar manfaat","en":"The Feeling fresh, hours later section: a photo of the cream''s texture beside a list of benefits"},"width":1600,"height":1000}]},{"title":{"id":"Toko dan halaman produk","en":"Shop and product pages"},"text":{"id":"Toko bisa disaring menurut jenis kulit atau terrain dan diurutkan menurut harga atau SPF, dan setiap kartu memakai warna terrain-nya. Halaman produk berpindah antara tube dan kotak kertas yang bisa diputar dengan diseret atau dengan tombol panah, dan di HP tombol Add to bag selalu terjangkau di bagian bawah.","en":"The shop filters by skin type or terrain and sorts by price or SPF, and every card wears its terrain colour. Product pages switch between the tube and a paper box you can spin by dragging or with the arrow keys, and on phones Add to bag stays within reach at the bottom."},"images":[{"url":"/media/seed/ranum-toko.webp","alt":{"id":"Toko Ranum disaring untuk kulit kering: Forest Calm, Desert Glow, Tropical Defense, dan The Journey Set","en":"The Ranum shop filtered for dry skin: Forest Calm, Desert Glow, Tropical Defense and The Journey Set"},"width":1600,"height":1000},{"url":"/media/seed/ranum-produk.webp","alt":{"id":"Halaman produk Forest Calm dengan kotak kertas hijau yang bisa diputar","en":"The Forest Calm product page showing the green paper box you can spin"},"width":1600,"height":1000},{"url":"/media/seed/ranum-hp-produk.webp","alt":{"id":"Halaman produk Desert Glow di HP","en":"The Desert Glow product page on a phone"},"width":600,"height":1298}]},{"title":{"id":"Kotak dari selembar kertas","en":"A box from one sheet of paper"},"text":{"id":"Setiap kotak berawal dari selembar kertas tanpa jendela plastik, dengan satu dari enam bunga yang ditekan timbul, bukan dicetak. Di halaman cerita, pola kotaknya terlipat sendiri saat digulir: rata, ditekan, lalu terlipat. Di beranda, cahaya mengikuti kursor supaya timbulnya terlihat.","en":"Every box starts as one sheet of paper with no plastic window, blind-embossed with one of six flowers instead of printed. On the story page the dieline folds itself as you scroll: flat, pressed, folded. On the homepage a light follows the cursor so the relief catches it."},"images":[{"url":"/media/seed/ranum-kotak.webp","alt":{"id":"Bagian One sheet of paper, folded: kotak Forest Calm setengah terlipat","en":"The One sheet of paper, folded section: the Forest Calm box half folded"},"width":1600,"height":1000},{"url":"/media/seed/ranum-bunga.webp","alt":{"id":"Bagian From nature, back to nature: enam bunga timbul dan angka 100%, 6, dan 4","en":"The From nature, back to nature section: six pressed flowers and the figures 100%, 6 and 4"},"width":1600,"height":1000}]},{"title":{"id":"Tas, checkout, dan terima kasih","en":"Bag, checkout and thank you"},"text":{"id":"Tas belanja menghitung sisa belanja sampai gratis ongkir di Rp 300.000. Checkout memeriksa nomor HP Indonesia dan kode pos lima angka begitu kolomnya ditinggalkan, menawarkan transfer virtual account, QRIS, atau bayar di tempat, dan tidak menagih apa pun karena ini preview. Halaman pesanan menyapa pembeli dengan namanya dan menjelaskan langkah bayar yang dipilih.","en":"The bag counts down to free shipping at Rp 300.000. Checkout checks an Indonesian mobile number and a five-digit postcode as soon as you leave each field, offers a virtual account transfer, QRIS or cash on delivery, and charges nothing because this is a preview. The order page greets the buyer by name and explains the next step for the payment chosen."},"images":[{"url":"/media/seed/ranum-checkout.webp","alt":{"id":"Halaman checkout Almost packed: kontak, alamat pengiriman, dan ringkasan dua produk","en":"The Almost packed checkout page: contact, delivery address and a summary of two products"},"width":1600,"height":1000},{"url":"/media/seed/ranum-pesanan.webp","alt":{"id":"Halaman terima kasih: Thank you, Rani, dengan ringkasan pesanan","en":"The thank-you page: Thank you, Rani, with the order summary"},"width":1600,"height":1000}]}]},{"type":"flow","title":{"id":"Dari tujuan ke kotak","en":"From a destination to the box"},"steps":[{"id":"Memilih tempat tujuan atau terrain","en":"Choose a destination or a terrain"},{"id":"Menjawab jenis kulit, lalu membaca alasannya","en":"Answer for your skin, then read why"},{"id":"Membuka produk: tube atau kotaknya","en":"Open the product: the tube or its box"},{"id":"Checkout: kontak, alamat, pengiriman, pembayaran","en":"Check out: contact, address, delivery, payment"},{"id":"Pesanan selesai, dikemas di kotak kertas bertimbul bunga","en":"Order placed, packed in a paper box pressed with a flower"}]},{"type":"decisions","title":{"id":"Keputusan yang melindungi bisnis","en":"Decisions that protect the business"},"items":[{"title":{"id":"Nama tempat, bukan angka","en":"Name the place, not the number"},"text":{"id":"SPF 35 dan SPF 40 terdengar mirip, jalan kota dan jalur hutan tidak. Karena itu setiap formula dinamai menurut tempat tujuannya, jadi pembeli tahu tube mana yang harus dibawa.","en":"SPF 35 and SPF 40 sound alike; city streets and forest trails don''t. So every formula is named after where it is headed, and shoppers know which tube to pack."}},{"title":{"id":"Warna yang memilah","en":"Colour does the sorting"},"text":{"id":"Satu warna dan satu bunga untuk setiap terrain, sama di tube, kotak, halaman produk, dan kartu toko. Pembeli menemukan formulanya sebelum sempat membaca.","en":"One colour and one flower per terrain, the same on the tube, the box, the product page and the shop card. Shoppers find their formula before they read a word."}},{"title":{"id":"Satu saran, dengan alasan","en":"One recommendation, with a reason"},"text":{"id":"Pencari shade memberi satu formula dan alasannya, bukan daftar lima pilihan, supaya pembeli tidak kembali bingung memilih di akhir.","en":"The finder gives one formula and its reason, not a list of five, so shoppers aren''t left choosing all over again at the end."}},{"title":{"id":"Tunjukkan kemasannya, jangan klaim","en":"Show the packaging, don''t claim it"},"text":{"id":"Kotaknya terlipat di layar dan bunganya ditekan timbul, bukan dicetak. Cerita kemasan yang kembali ke alam disampaikan lewat bendanya, bukan lewat paragraf janji.","en":"The box folds on screen and the flower is pressed, not printed. The story of packaging that goes back to nature is told by the object rather than a paragraph of promises."}}]},{"type":"numbers","title":{"id":"Dalam angka","en":"By the numbers"},"facts":[{"value":"7","label":{"id":"halaman, dari beranda sampai pesanan","en":"pages, from the homepage to the order"}},{"value":"5","label":{"id":"produk: empat formula dan satu set","en":"products: four formulas and a set"}},{"value":"6","label":{"id":"bunga timbul di kotak","en":"flowers pressed into the boxes"}},{"value":"2","label":{"id":"pertanyaan untuk menemukan formula","en":"questions to find your formula"}}],"stack":{"id":"Dibuat dengan HTML, CSS, dan JavaScript dalam satu file, dengan GSAP (ScrollTrigger, Flip) dan Lenis untuk gerak, WebGL untuk tekstur krim, serta huruf Inter, Inter Display, dan Playfair Display.","en":"Built with HTML, CSS and JavaScript in a single file, with GSAP (ScrollTrigger, Flip) and Lenis for motion, WebGL for the cream texture, and set in Inter, Inter Display and Playfair Display."}}]}'::jsonb where exists (select 1 from public.projects where id = 'a3299df1-e863-5bc9-b6ad-881a68531433' and slug = 'ranum') and not exists (select 1 from public.case_studies where project_slug = 'ranum');

-- Deretan klien di bawah hero: Ranum ditambahkan di ujung (dilewati bila sudah ada, deretannya sudah penuh, atau ruang Ranum tidak ditambahkan)
update public.sections set data = jsonb_set(data, '{clients,items}', coalesce(data->'clients'->'items', '[]'::jsonb) || '[{"name":"Ranum","font":"ranum","uppercase":false,"projectSlug":"ranum"}]'::jsonb) where key = 'hero' and exists (select 1 from public.projects where id = 'a3299df1-e863-5bc9-b6ad-881a68531433' and slug = 'ranum') and jsonb_typeof(data->'clients') = 'object' and case when jsonb_typeof(coalesce(data->'clients'->'items', '[]'::jsonb)) = 'array' then jsonb_array_length(coalesce(data->'clients'->'items', '[]'::jsonb)) <= 11 and not exists (select 1 from jsonb_array_elements(coalesce(data->'clients'->'items', '[]'::jsonb)) x where x->>'projectSlug' = 'ranum') else false end;

-- Kalimat yang menghitung jumlah karya (sebelas → dua belas), hanya bila belum Anda ubah dan ruang Ranum ditambahkan
update public.sections set data = jsonb_set(data, '{lede}', '{"id":"Studio Manager di Invisual Studio. Dua belas karya di halaman ini, dari sistem internal sampai situs merek, saya rancang dan bangun dari tampilan sampai kodenya. Lima di antaranya sudah tayang dan dipakai.","en":"Studio Manager at Invisual Studio. I designed and built the twelve projects on this page, from internal systems to brand sites, from the interface to the code. Five of them are live and in use."}'::jsonb) where key = 'hero' and exists (select 1 from public.projects where id = 'a3299df1-e863-5bc9-b6ad-881a68531433' and slug = 'ranum') and data->'lede' = '{"id":"Studio Manager di Invisual Studio. Sebelas karya di halaman ini, dari sistem internal sampai situs merek, saya rancang dan bangun dari tampilan sampai kodenya. Lima di antaranya sudah tayang dan dipakai.","en":"Studio Manager at Invisual Studio. I designed and built the eleven projects on this page, from internal systems to brand sites, from the interface to the code. Five of them are live and in use."}'::jsonb;
update public.sections set data = jsonb_set(data, '{intro}', '{"id":"Dua belas ruang, dua belas bisnis. Setiap ruang memakai warna dan huruf milik kliennya, karena sistem yang baik tampil sebagai brand Anda, bukan template saya.","en":"Twelve rooms, twelve businesses. Each room wears its client''s own colours and type, because a good system looks like your brand, not my template."}'::jsonb) where key = 'works' and exists (select 1 from public.projects where id = 'a3299df1-e863-5bc9-b6ad-881a68531433' and slug = 'ranum') and data->'intro' = '{"id":"Sebelas ruang, sebelas bisnis. Setiap ruang memakai warna dan huruf milik kliennya, karena sistem yang baik tampil sebagai brand Anda, bukan template saya.","en":"Eleven rooms, eleven businesses. Each room wears its client''s own colours and type, because a good system looks like your brand, not my template."}'::jsonb;
update public.site_settings set data = jsonb_set(data, '{seoDescription}', '{"id":"Portofolio Virgiawan Listanto, desainer dan pengembang produk digital di Bandung. Dua belas karya untuk bisnis nyata, dari sistem internal sampai situs merek.","en":"Portfolio of Virgiawan Listanto, a digital product designer and developer in Bandung. Twelve projects for real businesses, from internal systems to brand sites."}'::jsonb) where id = 1 and exists (select 1 from public.projects where id = 'a3299df1-e863-5bc9-b6ad-881a68531433' and slug = 'ranum') and data->'seoDescription' = '{"id":"Portofolio Virgiawan Listanto, desainer dan pengembang produk digital di Bandung. Sebelas karya untuk bisnis nyata, dari sistem internal sampai situs merek.","en":"Portfolio of Virgiawan Listanto, a digital product designer and developer in Bandung. Eleven projects for real businesses, from internal systems to brand sites."}'::jsonb;

insert into public.content_updates (version) values ('0.2.13');
raise notice 'Pembaruan isi v0.2.13 selesai.';
end
$upd$;
